package com.ecole.gestion_scolaire.payroll.repository; import com.ecole.gestion_scolaire.payroll.entity.Payroll; import org.springframework.data.jpa.repository.*; import java.util.*;
public interface PayrollRepository extends JpaRepository<Payroll,Long>{List<Payroll> findByPayrollPeriodIdOrderByEmployeePersonLastNameAscEmployeePersonFirstNameAsc(Long periodId); List<Payroll> findByEmployeeIdAndPayrollPeriodIdOrderByVersionNumberDesc(Long employeeId,Long periodId); Optional<Payroll> findFirstByEmployeeIdAndPayrollPeriodIdOrderByVersionNumberDesc(Long employeeId,Long periodId);}
